/* PRO MUSIC — inline asset map + runtime resolver (standalone export) */
window.__assetMap={
"assets/brand/promusic-logo.png":"data:image/png;base64,",
"assets/brand/logos/audio-technica.png":"data:image/png;base64,",
"assets/brand/logos/ayrton.png":"data:image/png;base64,",
"assets/brand/logos/chamsys.png":"data:image/png;base64,",
"assets/brand/logos/digico.png":"data:image/png;base64,",
"assets/brand/logos/directout.png":"data:image/png;base64,",
"assets/brand/logos/l-acoustics.png":"data:image/png;base64,",
"assets/brand/logos/luminex.png":"data:image/png;base64,",
"assets/brand/logos/naostage.png":"data:image/png;base64,",
"assets/projekty/ed-sheeran/cervena-show.jpg":"data:image/jpeg;base64,",
"assets/projekty/ed-sheeran/ohnostroj.jpg":"data:image/jpeg;base64,",
"assets/projekty/ed-sheeran/stage-modra.jpg":"data:image/jpeg;base64,",
"assets/projekty/ed-sheeran/sing-pultiky.jpg":"data:image/jpeg;base64,",
"assets/projekty/steel-arena/projekce-barvy.jpg":"data:image/jpeg;base64,",
"assets/projekty/steel-arena/projekce-led.jpg":"data:image/jpeg;base64,",
"assets/projekty/djkt-plzen/sal-pohled.jpg":"data:image/jpeg;base64,",
"assets/projekty/djkt-plzen/rig-svetla.jpg":"data:image/jpeg;base64,",
"assets/projekty/djkt-plzen/array-strop.jpg":"data:image/jpeg;base64,",
"assets/projekty/karlin/foh-jeviste.jpg":"data:image/jpeg;base64,",
"assets/projekty/karlin/zvukar-foh.jpg":"data:image/jpeg;base64,"
};
(function(){var M=window.__assetMap;
function fixImg(img){var s=img.getAttribute&&img.getAttribute("src");if(s&&s.indexOf("assets/")>=0&&s.indexOf("data:")<0){for(var k in M){if(s.indexOf(k)>=0){if(img.src!==M[k])img.src=M[k];return;}}}}
function fixBg(el){var st=el.getAttribute&&el.getAttribute("style");if(st&&st.indexOf("assets/")>=0&&st.indexOf("url(")>=0){var ns=st.replace(/url\((["\x27]?)(assets\/[^"\x27)]+)\1\)/g,function(m,q,p){return M[p]?('url("'+M[p]+'")'):m;});if(ns!==st)el.setAttribute("style",ns);}}
function pass(){document.querySelectorAll("img").forEach(fixImg);document.querySelectorAll('[style*="assets/"]').forEach(fixBg);}
var mo=new MutationObserver(function(ms){ms.forEach(function(m){if(m.type==="attributes"){if(m.target.tagName==="IMG")fixImg(m.target);else if(m.attributeName==="style")fixBg(m.target);}if(m.addedNodes)m.addedNodes.forEach(function(n){if(n.nodeType!==1)return;if(n.tagName==="IMG")fixImg(n);if(n.getAttribute&&n.getAttribute("style"))fixBg(n);if(n.querySelectorAll){n.querySelectorAll("img").forEach(fixImg);n.querySelectorAll('[style*="assets/"]').forEach(fixBg);}});});});
mo.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:["src","style"]});
if(document.readyState!=="loading")pass();document.addEventListener("DOMContentLoaded",pass);setTimeout(pass,300);setTimeout(pass,1200);
})();
